const $=id=>document.getElementById(id);
const savedSize=key=>[20,50,100].includes(Number(localStorage.getItem(key)))?Number(localStorage.getItem(key)):20;
const savedChatSize=()=>{const raw=localStorage.getItem('chatPageSize');if(raw==='all')return'all';const size=Number(raw);return Number.isInteger(size)&&size>=1&&size<=500?size:20;};
const state={view:null,items:[],listRows:[],directoryRows:[],fileGroups:[],fileRows:[],fileGroup:null,statsData:null,homeData:null,employees:[],employee:null,category:'group',selected:null,showRawRecords:false,loading:false,pending:false,role:null,employeePage:1,conversationPage:1,chatPage:1,chatPages:1,chatPageSize:savedChatSize(),messageType:'all',employeePageSize:savedSize('employeePageSize'),conversationPageSize:savedSize('conversationPageSize')};
const titles={home:'企业概况',group:'群聊会话',employees:'存档员工',files:'群文件内容',export:'会话导出',customers:'客户列表',groups:'客户群列表',customerStats:'客户数据',conversationStats:'会话数据',officialActivity:'官群活跃度',serviceMessages:'客服消息统计',settings:'设置',users:'用户管理'};
const menuOptions=['employees','group','export','files','customers','groups','customerStats','conversationStats','officialActivity','serviceMessages'];
const node=(tag,cls,text)=>{const x=document.createElement(tag);if(cls)x.className=cls;if(text!==undefined)x.textContent=text;return x;};
const stamp=ms=>ms?new Date(Number(ms)).toLocaleString('zh-CN'):'—';
const dayString=value=>{const date=value instanceof Date?value:new Date(value);return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;};
const readableCustomerName=value=>{const clean=String(value||'').replace(/[\uE000-\uF8FF\uFFFD\u0000-\u001F]/g,'').trim();return /[\p{L}\p{N}\p{Extended_Pictographic}]/u.test(clean)?clean:'';};
function prepareCustomers(rows){const collator=new Intl.Collator('zh-CN');return rows.map(r=>{const name=readableCustomerName(r.name)||readableCustomerName(r.group_nickname)||'未获取到可显示昵称';return {...r,raw_name:r.name,name};}).sort((a,b)=>{const rank=name=>name==='未获取到可显示昵称'?3:/[\u3400-\u9FFF]/u.test(name)?0:/[\p{L}\p{N}]/u.test(name)?1:2;return rank(a.name)-rank(b.name)||collator.compare(a.name,b.name)||collator.compare(a.userid,b.userid);});}
async function api(path,options){const opts={...(options||{})};if(opts.method&&!['GET','HEAD'].includes(opts.method.toUpperCase())&&String(path)!=='/api/login'&&state.csrfToken)opts.headers={...(opts.headers||{}),'X-CSRF-Token':state.csrfToken};const r=await fetch(path,opts);let d;try{d=await r.json();}catch{d={error:`HTTP ${r.status}`};}if(!r.ok)throw Error(d.error||`HTTP ${r.status}`);return d;}
const jsonOptions=(method,data)=>({method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
function error(box,e){box.replaceChildren(node('div','status',`读取失败：${e.message}`));}
function loginVisible(show){$('loginOverlay').style.display=show?'grid':'none';}
async function init(){try{const me=await api('/api/me');state.role=me.role;state.csrfToken=me.csrf_token;state.menuPermissions=me.role==='admin'?menuOptions:me.menu_permissions||[];$('accountName').textContent=`${me.username} · ${me.role==='admin'?'管理员':'查看者'}`;$('settingsBtn').hidden=me.role!=='admin';document.querySelectorAll('.nav-item').forEach(b=>{b.hidden=!state.menuPermissions.includes(b.dataset.view);});document.querySelectorAll('.nav-group').forEach(g=>{g.hidden=![...g.querySelectorAll('.nav-item')].some(b=>!b.hidden);});loginVisible(false);setView('home');return true;}catch{loginVisible(true);return false;}}
$('loginForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api('/api/login',jsonOptions('POST',{username:f.get('username'),password:f.get('password')}));if(await init()){$('loginError').textContent='';e.target.reset();}else{$('loginError').textContent='密码已验证，但浏览器未保存登录会话。请使用 HTTPS 地址访问，并检查 Secure Cookie 配置。';}}catch(err){$('loginError').textContent=err.message;}};
$('logoutBtn').onclick=async()=>{await api('/api/logout',{method:'POST'});location.reload();};
function applyTheme(){const dark=localStorage.getItem('viewerTheme')==='dark';document.body.classList.toggle('dark-theme',dark);$('themeToggle').textContent=dark?'☀':'☾';$('themeToggle').setAttribute('aria-label',dark?'切换浅色主题':'切换深色主题');}
$('themeToggle').onclick=()=>{localStorage.setItem('viewerTheme',document.body.classList.contains('dark-theme')?'light':'dark');applyTheme();};
applyTheme();
$('settingsBtn').onclick=()=>{document.querySelector('.account-menu').classList.remove('menu-open');settingsSection='system';setView('settings');};
$('accountTrigger').onclick=()=>document.querySelector('.account-menu').classList.toggle('menu-open');
document.querySelector('.account-menu').onmouseleave=e=>e.currentTarget.classList.remove('menu-open');
function setView(view){if(view==='settings'||view==='users'){if(state.role!=='admin')view='home';}else if(view!=='home'&&!state.menuPermissions?.includes(view))view='home';state.view=view;document.querySelector('.nav-item.active')?.classList.remove('active');document.querySelector(`[data-view="${view}"]`)?.classList.add('active');const employeeMode=view==='employees';document.body.classList.toggle('employee-mode',employeeMode);document.body.classList.toggle('home-mode',view==='home');document.body.classList.toggle('detail-only',['home','customers','groups','export','customerStats','conversationStats','officialActivity','serviceMessages','settings','users'].includes(view));$('employeePager').style.display=employeeMode?'flex':'none';$('conversationPager').style.display=employeeMode||view==='group'||view==='files'?'flex':'none';$('listSearch').parentElement.style.display=employeeMode||view==='group'||view==='files'?'flex':'none';$('groupDate').hidden=view!=='group';if(view==='group')$('groupDate').value=dayString(new Date());$('listSearch').placeholder=view==='files'?'搜索群名':'搜索群名或会话';$('listSearch').value='';$('chatToolbar').style.display='none';$('chatPager').style.display='none';$('chatContent').classList.remove('paged-table-view','export-page');$('listTitle').textContent=employeeMode?(state.employee?.name||'选择存档员工'):view==='files'?'所有群聊':titles[view];$('chatTitle').textContent=titles[view];$('chatSub').textContent='';$('conversationList').replaceChildren();$('chatContent').replaceChildren();$('conversationCount').textContent='';$('messageSearch').disabled=true;$('messageSearch').style.display=employeeMode||view==='group'?'':'none';$('directorySearch').hidden=!['customers','groups'].includes(view);$('fileSearch').hidden=view!=='files';$('fileStartDate').hidden=view!=='files';$('fileEndDate').hidden=view!=='files';$('downloadFilesBtn').hidden=view!=='files';$('fileAllBtn').hidden=true;$('fileAllBtn').setAttribute('aria-pressed','false');state.fileAll=false;$('fileSearch').value='';const fileStart=new Date();fileStart.setDate(fileStart.getDate()-6);$('fileStartDate').value=view==='files'?dayString(fileStart):'';$('fileEndDate').value=view==='files'?dayString(new Date()):'';$('downloadFilesBtn').disabled=true;$('directorySearch').value='';$('directorySearch').placeholder=view==='customers'?'搜索客户名称或ID':'搜索群名、群ID或群主';$('exportBtn').disabled=true;$('exportBtn').style.display=['home','settings','users','officialActivity','serviceMessages'].includes(view)?'none':'';state.selected=null;state.showRawRecords=false;$('rawToggle').hidden=true;$('rawToggle').setAttribute('aria-pressed','false');$('rawToggle').textContent='显示原始记录';state.listRows=[];state.directoryRows=[];state.fileRows=[];state.fileGroup=null;state.statsData=null;state.conversationPage=1;if(employeeMode){state.category='group';$('employeeDate').value=dayString(new Date());loadEmployeeList();if(state.employee)loadConversations();else $('chatContent').append(node('div','empty','请先选择存档员工'));}else if(view==='group'){loadConversations();}else loadSection();}
$('homeLink').onclick=()=>setView('home');
async function loadEmployeeList(){try{state.employees=await api('/api/archive-employees?date='+encodeURIComponent($('employeeDate').value));renderEmployees();$('exportBtn').disabled=false;if(!state.employee&&state.employees.length){state.employee=state.employees[0];renderEmployees();$('listTitle').textContent=state.employee.name||state.employee.userid;await loadConversations();}}catch(e){error($('employeeList'),e);}}
function renderEmployees(){const box=$('employeeList');box.replaceChildren();const q=$('employeeSearch').value.trim().toLowerCase();const filtered=state.employees.filter(x=>!q||`${x.name} ${x.userid} ${x.department}`.toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(filtered.length/state.employeePageSize));state.employeePage=Math.min(state.employeePage,pages);const start=(state.employeePage-1)*state.employeePageSize;for(const person of filtered.slice(start,start+state.employeePageSize)){const b=node('button','employee-row'+(state.employee?.userid===person.userid?' selected':''));b.append(node('span','avatar',person.name?.slice(0,1)||'员'));const body=node('span','body');body.append(node('div','title',person.name||person.userid),node('div','preview',`${person.group_count||0} 个群`));const counts=node('span','employee-count');counts.append(node('span','',`群消息 ${person.message_count||0}`),node('span','',`发送 ${person.sent_message_count||0}`));b.append(body,counts);b.onclick=()=>{state.employee=person;renderEmployees();$('listTitle').textContent=person.name||person.userid;loadConversations();};box.append(b);}if(!filtered.length)box.append(node('div','status','没有匹配的员工'));$('employeePageInfo').textContent=`${state.employeePage}/${pages}`;$('employeePrev').disabled=state.employeePage<=1;$('employeeNext').disabled=state.employeePage>=pages;box.scrollTop=0;}
$('employeeSearch').oninput=()=>{state.employeePage=1;renderEmployees();};$('employeeDate').onchange=()=>{state.employeePage=1;loadEmployeeList();if(state.employee)loadConversations();if(state.selected){$('startDate').value=$('employeeDate').value;$('endDate').value=$('employeeDate').value;resetMessagePage();}};
$('employeePageSize').value=String(state.employeePageSize);$('conversationPageSize').value=String(state.conversationPageSize);
$('employeePageSize').onchange=e=>{state.employeePageSize=Number(e.target.value);localStorage.setItem('employeePageSize',e.target.value);state.employeePage=1;renderEmployees();};
$('conversationPageSize').onchange=e=>{state.conversationPageSize=Number(e.target.value);localStorage.setItem('conversationPageSize',e.target.value);state.conversationPage=1;state.view==='files'?renderFileGroups($('chatContent')):renderConversations();};
$('employeePrev').onclick=()=>{state.employeePage--;renderEmployees();};$('employeeNext').onclick=()=>{state.employeePage++;renderEmployees();};
$('conversationPrev').onclick=()=>{state.conversationPage--;state.view==='files'?renderFileGroups($('chatContent')):renderConversations();};$('conversationNext').onclick=()=>{state.conversationPage++;state.view==='files'?renderFileGroups($('chatContent')):renderConversations();};
document.querySelectorAll('.nav-item').forEach(b=>{b.title=b.textContent;b.onclick=()=>setView(b.dataset.view);});
$('sidebarToggle').onclick=()=>{const collapsed=document.body.classList.toggle('sidebar-collapsed');$('sidebarToggle').setAttribute('aria-expanded',String(!collapsed));$('sidebarToggle').setAttribute('aria-label',collapsed?'展开左侧菜单':'收起左侧菜单');};
async function loadConversations(){if(document.body.classList.contains('employee-mode')&&!state.employee)return;const u=new URL('/api/conversations',location.href);u.searchParams.set('q',$('listSearch').value.trim());if(document.body.classList.contains('employee-mode')){u.searchParams.set('employee',state.employee.userid);u.searchParams.set('category','group');u.searchParams.set('date',$('employeeDate').value);}else{u.searchParams.set('scope','all-groups');u.searchParams.set('date',$('groupDate').value);}try{state.items=await api(u);state.conversationPage=1;renderConversations();$('exportBtn').disabled=false;if(!state.selected||!state.items.some(x=>x.id===state.selected.id)){if(state.items.length)select(state.items[0]);else{state.selected=null;$('chatContent').replaceChildren(node('div','empty','该条件下没有会话'));}}}catch(e){error($('conversationList'),e);}}
function renderConversations(){const box=$('conversationList');box.replaceChildren();const filtered=state.items.filter(x=>state.view==='export'||document.body.classList.contains('employee-mode')||x.kind===state.view);const pages=Math.max(1,Math.ceil(filtered.length/state.conversationPageSize));state.conversationPage=Math.min(state.conversationPage,pages);const start=(state.conversationPage-1)*state.conversationPageSize;$('conversationCount').textContent=`${filtered.length} 个`;for(const item of filtered.slice(start,start+state.conversationPageSize)){const b=node('button','conversation'+(item.id===state.selected?.id?' selected':''));b.append(node('span','avatar',item.kind==='group'?'群':item.title.slice(0,1)));const body=node('span','body');body.append(node('div','title',item.title),node('div','preview',item.preview||`[${item.kind}]`));b.append(body);if(item.msgtime)b.append(node('span','time',stamp(item.msgtime)));b.onclick=()=>select(item);box.append(b);}if(!filtered.length)box.append(node('div','status','没有匹配的会话'));$('conversationPageInfo').textContent=`${state.conversationPage}/${pages}`;$('conversationPrev').disabled=state.conversationPage<=1;$('conversationNext').disabled=state.conversationPage>=pages;box.scrollTop=0;if(state.view==='export')$('chatContent').append(node('div','status','选择会话后点击“导出”，下载可离线搜索的聊天网页。'));}
function select(item){state.selected=item;renderConversations();$('chatTitle').textContent=item.title;$('chatSub').textContent=item.id.startsWith('room:')?'群聊记录':'双人会话记录';$('messageSearch').disabled=false;$('exportBtn').disabled=false;$('chatToolbar').style.display='block';$('chatPager').style.display='flex';state.chatPage=1;state.messageType='all';document.querySelectorAll('.type-tab').forEach(b=>b.classList.toggle('active',b.dataset.type==='all'));$('senderFilter').value='';$('startDate').value=state.view==='employees'?$('employeeDate').value:state.view==='group'?$('groupDate').value:dayString(new Date());$('endDate').value=$('startDate').value;state.showRawRecords=false;$('rawToggle').hidden=false;$('rawToggle').setAttribute('aria-pressed','false');$('rawToggle').textContent='显示原始记录';loadMessages();}
function downloadCsv(filename,headers,rows){const cell=value=>{let s=String(value??'');if(/^[=+\-@]/.test(s.trimStart()))s="'"+s;return '"'+s.replaceAll('"','""')+'"';};const csv='\uFEFF'+[headers,...rows].map(row=>row.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=node('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportLink(id,format='html'){const u=new URL('/api/export',location.href);u.searchParams.set('conversation',id);if(format!=='html')u.searchParams.set('format',format);if(state.view==='export'){if(state.exportStartDate?.value)u.searchParams.set('start_date',state.exportStartDate.value);if(state.exportEndDate?.value)u.searchParams.set('end_date',state.exportEndDate.value);}return u.pathname+u.search;}
$('exportBtn').onclick=()=>{const v=state.view;if(v==='export'&&state.selected){location.href=exportLink(state.selected.id);return;}if(['employees','group'].includes(v)&&state.selected){location.href='/api/export?conversation='+encodeURIComponent(state.selected.id);return;}if(v==='customers')downloadCsv('客户列表.csv',['客户名称','客户ID','所在客户群数'],state.listRows.map(r=>[r.name,r.userid,r.group_count]));else if(v==='groups')downloadCsv('客户群列表.csv',['群ID','群名','群主','人数','来源'],state.listRows.map(r=>[r.roomid,r.room_name_display||r.room_name,r.owner_display||r.owner,r.member_count??'未同步',r.source_label]));else if(v==='export')downloadCsv('群聊会话列表.csv',['群名','群消息数','最新消息'],state.listRows.map(r=>[r.title,r.message_count,stamp(r.msgtime)]));else if(v==='employees')downloadCsv('存档员工.csv',['员工姓名','员工ID','所在群数','所选日期群消息数','所选日期发送数'],state.employees.map(r=>[r.name,r.userid,r.group_count,r.message_count,r.sent_message_count]));else if(v==='group')downloadCsv('群聊会话列表.csv',['群名','群消息数','最新消息'],state.items.map(r=>[r.title,r.message_count,stamp(r.msgtime)]));else if(v==='files'){if(state.fileGroup)downloadCsv(`${state.fileGroup.room_name||'群'}文件.csv`,['文件名','类型','发送人','时间','状态'],state.fileRows.map(r=>[r.file_name||r.filename||r.msgid,r.msgtype,r.sender_name||r.from_user,stamp(r.msgtime),r.download_status]));else downloadCsv('群文件列表.csv',['群名','群ID','人数'],state.fileGroups.map(r=>[r.room_name,r.roomid,r.member_count]));}else if(['customerStats','conversationStats'].includes(v)&&state.statsData){const d=state.statsData;downloadCsv(`${titles[v]}.csv`,['日期','指标','数值'],[...Object.entries(d.summary||{}).map(([k,value])=>['',k,value]),...(d.daily||[]).map(r=>[r.day,'每日数据',r.value])]);}};
$('rawToggle').onclick=()=>{state.showRawRecords=!state.showRawRecords;$('rawToggle').setAttribute('aria-pressed',String(state.showRawRecords));$('rawToggle').textContent=state.showRawRecords?'隐藏原始记录':'显示原始记录';document.querySelectorAll('#chatContent .raw-data').forEach(el=>{el.hidden=!state.showRawRecords;});};
function safeLink(url,label){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))return node('span','',label);const a=node('a','',label);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';return a;}catch{return node('span','',label);}}
function renderPayload(container,m){
  const p=m.payload||{},d=p[m.msgtype]||{};
  if(m.msgtype==='qydiskfile'){
    const info=p.info||d,filename=info.filename||m.file_name||'群文件',url=info.url;
    const file=node('div','archive-file');file.append(node('span','archive-file-icon','📎'),url?safeLink(url,filename):node('span','',filename));container.append(file);
  }else if(m.msgtype==='link'){
    const url=d.link_url||d.url;if(url)container.append(safeLink(url,d.title||url));
    if(d.description)container.append(node('div','detail',d.description));
  }else if(m.msgtype==='location'){
    container.append(node('div','detail',[d.title,d.address].filter(Boolean).join(' · ')));
  }else if(m.msgtype==='weapp'){
    container.append(node('div','detail',d.displayname||d.title||'小程序'));
  }else if(m.msgtype==='card'){
    container.append(node('div','detail',[d.corpname,d.userid].filter(Boolean).join(' · ')));
  }else if(m.msgtype==='mixed'){
    for(const item of d.item||[]){
      if(item.type==='text'){
        let value=item.content||'';try{const parsed=JSON.parse(value);value=parsed.content||value;}catch{}
        if(value)container.append(node('div','',value));
      }else container.append(node('div','detail',`[${item.type||'内容'}]`));
    }
  }else if(m.msgtype==='markdown'){
    const value=(p.info||{}).content;if(value)container.append(node('div','',value));
  }else if(m.msgtype==='sphfeed'){
    if(d.sph_name)container.append(node('div','',d.sph_name));
    if(d.feed_desc)container.append(node('div','detail',d.feed_desc));
  }else if(m.msgtype==='external_redpacket'){
    const packet=p.redpacket||{};container.append(node('div','',packet.title||'微信红包'));
  }
}
function openMediaDialog(media,label){const source='/api/media/'+media.id;const dialog=node('dialog','media-dialog'),head=node('header'),close=node('button','dialog-close','关闭');close.onclick=()=>dialog.close();head.append(node('strong','',label),close);dialog.append(head);if(['image','emotion'].includes(media.msgtype)){const img=node('img');img.src=source;img.alt=label;dialog.append(img);}else if(media.msgtype==='video'){const video=node('video');video.controls=true;video.autoplay=true;video.src=source;dialog.append(video);}else if(media.msgtype==='voice'){const audio=node('audio');audio.controls=true;audio.autoplay=true;audio.src=source+'/play';dialog.append(audio,node('p','detail','如浏览器无法播放 AMR 音频，请使用下方链接打开原文件。'));}if(!['image','emotion'].includes(media.msgtype)){const link=node('a','media-open','在新窗口打开原文件 ↗');link.href=source;link.target='_blank';link.rel='noopener noreferrer';dialog.append(link);}dialog.onclick=e=>{if(e.target===dialog)dialog.close();};dialog.onclose=()=>dialog.remove();document.body.append(dialog);dialog.showModal();}
