async function loadMessages(){
  if(!state.selected)return;
  if(state.loading){state.pending=true;state.messageVersion=(state.messageVersion||0)+1;return;}
  state.loading=true;const version=state.messageVersion=(state.messageVersion||0)+1;
  const box=$('chatContent'),id=state.selected.id,all=state.chatPageSize==='all',batchSize=all?500:state.chatPageSize;
  box.replaceChildren(node('div','status','读取中…'));
  const makeUrl=page=>{const u=new URL('/api/messages',location.href);u.searchParams.set('conversation',id);u.searchParams.set('page',page);u.searchParams.set('page_size',batchSize);u.searchParams.set('type',state.messageType);if($('messageSearch').value.trim())u.searchParams.set('q',$('messageSearch').value.trim());if($('senderFilter').value.trim())u.searchParams.set('sender',$('senderFilter').value.trim());if($('startDate').value)u.searchParams.set('start_ms',new Date($('startDate').value+'T00:00:00').getTime());if($('endDate').value)u.searchParams.set('end_ms',new Date($('endDate').value+'T00:00:00').getTime()+86400000);return u;};
  try{
    let data,loaded=0,page=all?1:state.chatPage;
    do{
      data=await api(makeUrl(page));
      if(state.selected?.id!==id||version!==state.messageVersion)return;
      const elements=data.messages.map(m=>{if(m.msgtype==='revoke')m.content='撤回了一条消息';const item=messageNode(m);if(m.recalled)item.querySelector('.meta')?.append(node('span','recalled-badge','已撤回'));return item;});
      if(page===(all?1:state.chatPage))box.replaceChildren(...elements);else box.prepend(...elements);
      loaded+=data.messages.length;
      if(all)$('chatCount').textContent=`加载中 ${loaded}/${data.total} 条`;
      page++;
    }while(all&&page<=data.pages&&data.messages.length);
    if(!loaded)box.append(node('div','empty','该条件下没有消息'));
    state.chatPages=all?1:data.pages;
    const today=dayString(new Date()),isToday=$('startDate').value===today&&$('endDate').value===today;
    const period=isToday?'今日':$('startDate').value||$('endDate').value?'筛选结果':'全部记录';
    $('chatSub').textContent=`${id.startsWith('room:')?'群聊记录':'双人会话记录'} · ${period} ${data.total} 条${id.startsWith('room:')&&state.selected?.message_count!=null?' · 总计 '+state.selected.message_count+' 条':''}`;
    $('chatCount').textContent=`${period} ${data.total} 条`;
    $('chatPageInfo').textContent=all?'全部':`${data.page}/${data.pages}`;
    $('chatPrev').disabled=all||state.chatPage<=1;
    $('chatNext').disabled=all||state.chatPage>=data.pages;
    $('chatPageJump').max=String(data.pages);$('chatPageJump').value=String(all?1:data.page);
    box.scrollTop=box.scrollHeight;
  }catch(e){error(box,e);}finally{state.loading=false;if(state.pending){state.pending=false;loadMessages();}}
}
