function toolChart(host,title,rows,series){
  host.replaceChildren(node('h3','',title));
  if(!rows.length){host.append(node('p','status','所选日期没有记录'));return;}
  const legend=node('div','tool-legend');series.forEach(s=>{const item=node('span','',s.label);item.style.setProperty('--series-color',s.color);legend.append(item);});host.append(legend);
  const width=800,height=260,left=48,right=18,top=30,bottom=34,high=Math.max(1,...rows.flatMap(r=>series.map(s=>Number(r[s.key]||0))))*1.12;
  const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('role','img');svg.setAttribute('aria-label',title);
  const add=(tag,attrs,label)=>{const el=document.createElementNS(svg.namespaceURI,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));if(label!==undefined)el.textContent=label;svg.append(el);};
  const x=i=>left+i*(width-left-right)/Math.max(1,rows.length-1),y=v=>height-bottom-Number(v||0)/high*(height-top-bottom);
  for(let i=0;i<=4;i++){const yy=y(high*i/4);add('line',{x1:left,y1:yy,x2:width-right,y2:yy,stroke:'var(--chart-grid, #e6eaf0)'});add('text',{x:left-8,y:yy+4,'text-anchor':'end','font-size':11,fill:'var(--chart-label, #8190a3)'},Math.round(high*i/4));}
  series.forEach((s,seriesIndex)=>{const points=rows.map((r,i)=>`${x(i)},${y(r[s.key])}`).join(' ');add('polyline',{points,fill:'none',stroke:s.color,'stroke-width':2.5});rows.forEach((r,i)=>{const value=Number(r[s.key]||0),show=i%Math.max(1,Math.ceil(rows.length/30))===0||i===rows.length-1;if(show){add('circle',{cx:x(i),cy:y(value),r:2.5,fill:s.color});add('text',{x:x(i)+(i===0?5:i===rows.length-1?-5:0),y:y(value)-8-seriesIndex*12,'text-anchor':i===0?'start':i===rows.length-1?'end':'middle','font-size':11,'font-weight':600,fill:s.color},value.toLocaleString('zh-CN'));}});});
  rows.forEach((r,i)=>{if(i%Math.max(1,Math.ceil(rows.length/7))===0||i===rows.length-1)add('text',{x:x(i),y:height-8,'text-anchor':'middle','font-size':11,fill:'var(--chart-label, #8190a3)'},String(r.day||'').slice(5));});host.append(svg);
}
