let settingsSection='system';
async function renderSystemSettings(box){
  const wrap=node('div','settings settings-hub'),intro=node('p','settings-intro','集中管理系统参数、用户权限和操作记录。'),tabs=node('div','settings-tabs'),body=node('div','settings-body');
  for(const [key,label] of [['system','⚙ 系统设置'],['users','♙ 用户与权限'],['logs','⌁ 操作日志']]){const button=node('button','settings-tab'+(settingsSection===key?' active':''),label);button.onclick=()=>{settingsSection=key;renderSystemSettings(box);};tabs.append(button);}
  wrap.append(intro,tabs,body);box.replaceChildren(wrap);
  if(settingsSection==='users'){await renderSettings(body);return;}
  if(settingsSection==='logs'){body.append(node('h3','','操作日志'),node('p','detail','查看器配置与用户管理操作记录。'));await renderAuditLogs(body);return;}
  body.append(node('h3','','系统设置'),node('p','detail','管理查看器参数与集成入口。'));
  const cards=node('div','settings-cards');
  const addCard=(title,description,action)=>{const card=node('button','settings-card');card.append(node('strong','',title),node('span','',description),node('b','','查看设置 →'));card.onclick=action;cards.append(card);};
  addCard('客服消息统计','自定义参与客服消息统计的员工名单。',()=>renderServiceStaffSettings(body));
  addCard('内部系统免密登录','查看免登接入状态及用户密钥使用方式。',()=>renderSsoSettings(body));
  body.append(cards,node('p','settings-config-note','数据库连接、监听端口及媒体目录通过服务端 .env 配置。'));
}
async function renderServiceStaffSettings(box){
  const wrap=node('div','settings-subpage'),back=node('button','settings-back','← 返回系统设置');back.onclick=()=>renderSystemSettings($('chatContent'));wrap.append(back);
  const section=node('section','service-staff-settings'),heading=node('h3','','客服消息统计人员'),help=node('p','detail','已添加的人员参与客服消息统计。点击“修改”后，可从下拉框添加、全选或删除人员。');
  const toolbar=node('div','service-staff-toolbar'),status=node('p','service-staff-status'),list=node('div','service-staff-list');section.append(heading,help,toolbar,status,list);wrap.append(section);box.replaceChildren(wrap);
  try{
    const data=await api('/api/settings/service-staff'),byId=new Map(data.users.map(u=>[u.userid,u])),selected=new Set(data.selected),saved=new Set(data.selected);let editing=false;
    const draw=()=>{
      toolbar.replaceChildren();list.replaceChildren();status.textContent=`已添加 ${selected.size} 人 · ${data.source==='custom'?'自定义名单':'部门默认名单'}`;
      if(editing){const search=node('input'),pick=node('select'),all=node('button','small-button','全选'),clear=node('button','small-button','清空'),save=node('button','small-button service-staff-save','保存人员'),cancel=node('button','small-button','取消'),reset=node('button','small-button','恢复部门默认人员');search.type='search';search.placeholder='搜索姓名、ID或部门';pick.setAttribute('aria-label','选择客服统计人员');
        const populate=()=>{const q=search.value.trim().toLowerCase();pick.replaceChildren();const prompt=node('option','','选择一名员工');prompt.value='';pick.append(prompt);for(const user of data.users){if(selected.has(user.userid)||q&&!`${user.name||''} ${user.userid} ${user.department||''}`.toLowerCase().includes(q))continue;const option=node('option','',`${user.name||user.userid} · ${user.userid}`);option.value=user.userid;pick.append(option);}pick.value='';};
        search.oninput=populate;pick.onchange=()=>{if(pick.value){selected.add(pick.value);draw();}};all.onclick=()=>{data.users.forEach(u=>selected.add(u.userid));draw();};clear.onclick=()=>{selected.clear();draw();};cancel.onclick=()=>{selected.clear();saved.forEach(id=>selected.add(id));editing=false;draw();};
        save.onclick=async()=>{save.disabled=true;try{await api('/api/settings/service-staff',jsonOptions('PUT',{selected:[...selected]}));saved.clear();selected.forEach(id=>saved.add(id));data.source='custom';editing=false;draw();}catch(e){status.textContent=`保存失败：${e.message}`;save.disabled=false;}};
        reset.onclick=async()=>{try{await api('/api/settings/service-staff',{method:'DELETE'});await renderServiceStaffSettings(box);}catch(e){status.textContent=`恢复失败：${e.message}`;}};
        toolbar.append(search,pick,all,clear,save,cancel,reset);populate();
      }else{const modify=node('button','small-button','修改');modify.onclick=()=>{editing=true;draw();};toolbar.append(modify);}
      for(const id of selected){const user=byId.get(id),row=node('div','service-staff-row');row.append(node('span','',user?.name||id),node('small','',`${id}${user?.department?' · 部门 '+user.department:''}`));if(editing){const remove=node('button','service-staff-remove','移除');remove.onclick=()=>{selected.delete(id);draw();};row.append(remove);}list.append(row);}
      if(!selected.size)list.append(node('p','service-staff-empty','尚未添加人员，点击“修改”选择员工。'));
    };
    draw();
  }catch(e){error(list,e);}
}
async function renderSsoSettings(box){
  const wrap=node('div','settings-subpage'),back=node('button','settings-back','← 返回系统设置');back.onclick=()=>renderSystemSettings($('chatContent'));wrap.append(back,node('h3','','内部系统免密登录'));
  if(state.role!=='admin'){wrap.append(node('p','detail','仅管理员可配置免登授权。'));box.replaceChildren(wrap);return;}
  const status=node('p','detail','读取配置中…');wrap.append(status,node('p','detail','在“用户与权限”中为用户生成专属免登密钥。密钥只显示一次；重置或吊销后，旧密钥、未消费票据及旧免登会话立即失效。'),node('p','detail','IT小爱可向 POST /api/sso/ticket 发送 X-Aura-SSO-Key 和 JSON userId；userId 必须与此页绑定的账号一致。也兼容原有 X-SSO-Key 方式。浏览器只接收一次性 loginUrl。'));box.replaceChildren(wrap);
  try{const data=await api('/api/settings/sso-info');status.textContent=data.ready?`免登服务已配置 · ${data.origin}`:'免登服务未启用：请配置 VIEWER_PUBLIC_ORIGIN 和 VIEWER_COOKIE_SECURE=true，然后重启服务。';}catch(e){error(wrap,e);}
}
async function renderAuditLogs(box){
  if(state.role!=='admin'){box.append(node('p','detail','仅管理员可查看操作日志。'));return;}
  const host=node('div');box.append(host);try{const rows=await api('/api/settings/audit');pagedTable(host,rows,['时间（UTC）','操作人','操作','详情'],r=>[r.created_at,r.actor,r.action,r.detail],'auditPageSize');}catch(e){error(host,e);}
}
async function renderFiles(box){if(!$('fileStartDate').value){const d=new Date();d.setDate(d.getDate()-6);$('fileStartDate').value=dayString(d);}if(!$('fileEndDate').value)$('fileEndDate').value=dayString(new Date());const start=$('fileStartDate').value,end=$('fileEndDate').value;if(start>end){box.replaceChildren(node('div','status','结束日期不能早于开始日期'));return;}const u=new URL('/api/file-groups',location.href);u.searchParams.set('start_ms',new Date(start+'T00:00:00').getTime());u.searchParams.set('end_ms',new Date(end+'T00:00:00').getTime()+86400000);const rows=await api(u);const current=state.fileGroup?.roomid;state.fileGroups=rows;state.fileGroup=rows.find(r=>r.roomid===current)||null;$('exportBtn').disabled=false;state.conversationPage=1;if(state.fileGroup)renderFileRows();else box.replaceChildren(node('div','empty','从中间选择群聊查看文件'));renderFileGroups(box);}
function renderFileRows(){
  const box=$('chatContent');if(state.view!=='files'||!state.fileGroup)return;
  const q=$('fileSearch').value.trim().toLocaleLowerCase(),start=state.fileAll?'':$('fileStartDate').value,end=state.fileAll?'':$('fileEndDate').value;
  $('fileAllBtn').hidden=false;$('fileAllBtn').setAttribute('aria-pressed',String(!!state.fileAll));$('fileStartDate').disabled=$('fileEndDate').disabled=!!state.fileAll;
  const rows=state.fileRows.filter(r=>{const day=dayString(Number(r.msgtime));return(!q||`${r.file_name||r.filename||''} ${r.sender_name||r.from_user||''}`.toLocaleLowerCase().includes(q))&&(!start||day>=start)&&(!end||day<=end);});
  state.visibleFileRows=rows;const selected=state.selectedFileIds||new Set();
  box.replaceChildren(table(['选择','文件','类型','发送人','时间','状态'],rows,r=>{const check=node('input');check.type='checkbox';check.checked=selected.has(r.id);check.setAttribute('aria-label',`选择 ${r.file_name||r.filename||r.msgid}`);check.onchange=()=>{check.checked?selected.add(r.id):selected.delete(r.id);$('downloadFilesBtn').disabled=!selected.size;$('downloadFilesBtn').textContent=selected.size?`批量下载 (${selected.size})`:'批量下载';};const a=node('a','',r.file_name||r.filename||r.msgid);a.href='/api/media/'+r.id;a.target='_blank';a.rel='noopener noreferrer';return[check,a,r.msgtype,r.sender_name||r.from_user,stamp(r.msgtime),r.download_status];}));
  if(!rows.length)box.append(node('div','status','该筛选条件下没有文件记录'));
  $('chatSub').textContent=`${state.fileAll?'全部文件':'所选日期文件'} ${rows.length} / ${state.fileRows.length} 个`;
}
function renderFileGroups(box){
  const list=$('conversationList');list.replaceChildren();const q=$('listSearch').value.trim().toLowerCase();const groups=state.fileGroups.filter(g=>!q||`${g.room_name} ${g.roomid}`.toLowerCase().includes(q));const pages=Math.max(1,Math.ceil(groups.length/state.conversationPageSize));state.conversationPage=Math.min(state.conversationPage,pages);$('conversationCount').textContent=`${groups.length} 个`;$('conversationPageInfo').textContent=`${state.conversationPage}/${pages}`;$('conversationPrev').disabled=state.conversationPage<=1;$('conversationNext').disabled=state.conversationPage>=pages;const start=(state.conversationPage-1)*state.conversationPageSize;
  for(const group of groups.slice(start,start+state.conversationPageSize)){const b=node('button','conversation'+(state.fileGroup?.roomid===group.roomid?' selected':''));b.append(node('span','avatar','群'));const body=node('span','body');body.append(node('div','title',group.room_name||group.roomid),node('div','preview',`${$('fileStartDate').value.slice(5)}–${$('fileEndDate').value.slice(5)} · 消息 ${group.message_count||0} · 文件 ${group.file_count||0}`));b.append(body);b.onclick=async()=>{state.fileGroup=group;state.fileRows=[];state.fileAll=false;state.selectedFileIds=new Set();$('downloadFilesBtn').disabled=true;$('downloadFilesBtn').textContent='批量下载';$('fileSearch').value='';list.querySelector('.selected')?.classList.remove('selected');b.classList.add('selected');$('chatTitle').textContent=group.room_name||group.roomid;box.replaceChildren(node('div','status','读取中…'));try{state.fileRows=await api('/api/files?roomid='+encodeURIComponent(group.roomid));renderFileRows();}catch(e){error(box,e);}};list.append(b);}
  if(!groups.length)list.append(node('div','status','没有匹配的群聊'));list.scrollTop=0;
}
$('fileSearch').oninput=renderFileRows;$('fileStartDate').onchange=()=>renderFiles($('chatContent')).catch(e=>error($('chatContent'),e));$('fileEndDate').onchange=()=>renderFiles($('chatContent')).catch(e=>error($('chatContent'),e));
$('fileAllBtn').onclick=()=>{state.fileAll=!state.fileAll;renderFileRows();};
$('downloadFilesBtn').onclick=async()=>{if(!state.fileGroup||!state.selectedFileIds?.size)return;const button=$('downloadFilesBtn');button.disabled=true;try{const response=await fetch('/api/files/batch-download',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':state.csrfToken},body:JSON.stringify({roomid:state.fileGroup.roomid,ids:[...state.selectedFileIds]})});if(!response.ok){const data=await response.json();throw Error(data.error||`HTTP ${response.status}`);}const url=URL.createObjectURL(await response.blob()),a=node('a');a.href=url;a.download='群文件.zip';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){alert(`下载失败：${e.message}`);}finally{button.disabled=false;}};
async function renderSettings(box){
  const wrap=node('div','settings-users-page'),top=node('div','settings-users-heading'),headingBlock=node('div');headingBlock.append(node('h3','','用户与权限'),node('p','detail','管理账号、左侧菜单权限和用户专属免登密钥。'));top.append(headingBlock);wrap.append(top);box.replaceChildren(wrap);
  if(state.role!=='admin'){wrap.append(node('p','detail','仅管理员可以管理用户。'));return;}
  const add=node('button','settings-add-user','＋ 新增用户'),list=node('div','settings-user-list'),editor=node('div','settings-user-editor');top.append(add);wrap.append(list,editor);
  const rows=await api('/api/users'),current=sessionName();
  const showForm=(person=null,passwordOnly=false)=>{editor.replaceChildren();const form=node('form','settings-user-form');form.append(node('h3','',person?(passwordOnly?`修改 ${person.display_name||person.username} 的密码`:`编辑 ${person.display_name||person.username}`):'新增用户'));
    const field=(label,name,value='',type='text')=>{const holder=node('label','settings-form-field'),input=node('input');holder.append(node('span','',label),input);input.name=name;input.type=type;input.value=value;holder.append(input);form.append(holder);return input;};
    let permissionGrid=null;if(!passwordOnly){field('用户名','username',person?.username||'').required=true;field('显示名称','display_name',person?.display_name||'');field('IT小爱 userId（可选）','sso_external_user_id',person?.sso_external_user_id||'');const roleWrap=node('label','settings-form-field'),role=node('select');role.name='role';for(const [value,label] of [['viewer','查看者'],['admin','管理员']]){const option=node('option','',label);option.value=value;role.append(option);}role.value=person?.role||'viewer';roleWrap.append(node('span','','角色'),role);form.append(roleWrap);const permissions=node('div','settings-form-permissions');permissions.append(node('strong','','左侧菜单权限'),node('p','detail','管理员拥有全部菜单；查看者仅可访问勾选的菜单。'));permissionGrid=node('div','settings-permission-grid');const allowed=new Set(person?.menu_permissions||[]);for(const key of menuOptions){const label=node('label','settings-permission-option'),checkbox=node('input');checkbox.type='checkbox';checkbox.value=key;checkbox.checked=allowed.has(key);label.append(checkbox,node('span','',titles[key]));permissionGrid.append(label);}permissions.append(permissionGrid);form.append(permissions);}
    const pass=field(passwordOnly?'新密码':person?'新密码（留空则不修改）':'登录密码','new_password_input','','password');pass.required=passwordOnly||!person;pass.autocomplete='new-password';let passwordTouched=false;pass.oninput=()=>{passwordTouched=true;};
    const actions=node('div','settings-form-actions'),submit=node('button','settings-add-user',person?'保存修改':'添加用户'),cancel=node('button','small-button','取消'),message=node('p','form-error');submit.type='submit';cancel.type='button';cancel.onclick=()=>editor.replaceChildren();actions.append(submit,cancel);form.append(actions,message);editor.append(form);
    form.onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(form));if(permissionGrid)values.menu_permissions=[...permissionGrid.querySelectorAll('input:checked')].map(x=>x.value);if(passwordTouched&&values.new_password_input)values.password=values.new_password_input;delete values.new_password_input;try{await api(person?`/api/users/${person.id}`:'/api/users',jsonOptions(person?'PATCH':'POST',values));await renderSettings(box);}catch(e){message.textContent=e.message;}};
  };
  add.onclick=()=>showForm();
  for(const person of rows){const card=node('div','settings-user-card'),avatar=node('span','settings-user-avatar',(person.display_name||person.username).slice(0,1)),identity=node('div','settings-user-identity');identity.append(node('strong','',person.display_name||person.username),node('small','',`${person.username} · ${person.role==='admin'?'全部菜单':(person.menu_permissions?.length||0)+' 项菜单'}`));if(person.sso_external_user_id)identity.append(node('small','',`IT小爱 userId：${person.sso_external_user_id}`));const role=node('span','settings-user-role',person.role==='admin'?'管理员':'查看者'),actions=node('div','settings-user-actions'),authStatus=node('span','settings-user-state',person.has_sso_key?`免登已授权 · ${person.sso_created_at||'时间未知'}`:person.sso_created_at?`免登已吊销 · 上次生成 ${person.sso_created_at}`:'免登未授权');
    const password=node('button','small-button','修改密码'),edit=node('button','small-button','编辑权限'),toggle=node('button','small-button',person.enabled?'停用':'启用'),key=node('button','small-button',person.has_sso_key?'重置免登密钥':'生成免登密钥');password.onclick=()=>showForm(person,true);edit.onclick=()=>showForm(person);toggle.disabled=person.username===current;toggle.onclick=async()=>{try{await api(`/api/users/${person.id}`,jsonOptions('PATCH',{enabled:!person.enabled}));renderSettings(box);}catch(e){editor.replaceChildren(node('p','form-error',e.message));}};key.disabled=!person.enabled;key.onclick=async()=>{try{const result=await api(`/api/users/${person.id}/sso-key`,{method:'POST'});editor.replaceChildren(node('h3','',`${person.display_name||person.username} 的免登密钥`),node('p','detail','请立即保存到调用方服务端。明文只显示这一次，关闭后无法再次查看。'));const value=node('input','settings-secret');value.value=result.key;value.readOnly=true;editor.append(value);key.textContent='重置免登密钥';revoke.hidden=false;authStatus.textContent=`免登已授权 · ${result.created_at}`;}catch(e){editor.replaceChildren(node('p','form-error',e.message));}};const revoke=node('button','small-button','吊销免登授权');revoke.hidden=!person.has_sso_key;revoke.onclick=async()=>{try{await api(`/api/users/${person.id}/sso-key`,{method:'DELETE'});renderSettings(box);}catch(e){editor.replaceChildren(node('p','form-error',e.message));}};actions.append(password,key,revoke,toggle,edit);card.append(avatar,identity,role,node('span','settings-user-state',person.enabled?'启用':'停用'),authStatus,actions);list.append(card);}
}
function sessionName(){return $('accountName').textContent.split(' · ')[0];}
let timer;$('groupDate').onchange=()=>{if(state.view==='files'){renderFiles($('chatContent')).catch(e=>error($('chatContent'),e));return;}if(state.view!=='group')return;loadConversations();if(state.selected){$('startDate').value=$('groupDate').value;$('endDate').value=$('groupDate').value;resetMessagePage();}};$('listSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(()=>{if(state.view==='files'){state.conversationPage=1;renderFileGroups($('chatContent'));}else loadConversations();},250);};$('messageSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(resetMessagePage,250);};init();
